import "server-only";
import { db } from "@/lib/db";
import { inngest } from "@/lib/inngest-client";

export async function cleanupExpiredRateLimits() {
  let deleted = 0;
  // Bound daily work to 10,000 rows. Locked budgets wait for a later pass.
  for (let batch = 0; batch < 20; batch++) {
    const count =
      await db.$executeRaw`DELETE FROM "RateLimitBucket" WHERE id IN (SELECT id FROM "RateLimitBucket" WHERE "cleanupAt"<clock_timestamp()-interval '1 day' ORDER BY "cleanupAt",id LIMIT 500 FOR UPDATE SKIP LOCKED)`;
    deleted += count;
    if (count < 500) break;
  }
  return { deleted };
}

export const rateLimitCleanup = inngest.createFunction(
  {
    id: "rate-limit-cleanup",
    triggers: { cron: "0 4 * * *" },
    concurrency: 1,
  },
  ({ step }) => step.run("cleanup-rate-buckets", cleanupExpiredRateLimits),
);
